        counts = {}
        for l in lines:
            ck = l['count_key']
            counts[ck] = counts.get(ck, 0) + 1
        print(f'{part}: {len(lines)} instances, count_keys: {counts}')
    except Exception as e:
        print(f'{part}: {e}')
